namespace SchoolManagement.Infrastructure.Licensing.Ed25519;

/// <summary>
/// The only key material shipped with the application: the Ed25519 public key.
/// It is a compile-time constant on purpose. Rotating it means publishing a new
/// build, not editing an environment variable on the customer machine (an
/// env-var override would let anyone replace the trust root).
///
/// The matching private key is generated by <c>tools/SchoolManagement.LicenseTool</c>
/// and must never be committed. See <c>docs/LICENSING.md</c>.
/// </summary>
public static class LicensePublicKey
{
    public const string Base64 = "SltgqsjHN0kCA1TuHEv4B5fiSBZCZNVS1yLo+GDN5pc=";

    private static readonly byte[] KeyBytes = Convert.FromBase64String(Base64);

    public static byte[] ToArray() => (byte[])KeyBytes.Clone();
}
